import{_ as t,c as n,o as s,j as a,a as l}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"易纂言卷十一","description":"易纂言 - 易纂言卷十一","frontmatter":{"title":"易纂言卷十一","description":"易纂言 - 易纂言卷十一"},"headers":[],"relativePath":"zh/classics/zuanyan/012.md","filePath":"zh/classics/zuanyan/012.md"}'),r={name:"zh/classics/zuanyan/012.md"};function c(o,e,i,p,d,u){return s(),n("div",null,[...e[0]||(e[0]=[a("h1",{id:"易纂言卷十一",tabindex:"-1"},[l("易纂言卷十一 "),a("a",{class:"header-anchor",href:"#易纂言卷十一","aria-label":"Permalink to “易纂言卷十一”"},"​")],-1),a("p",null,"钦定四库全书",-1),a("p",null,"元吴澄撰",-1),a("p",null,"序卦传 羲皇六十四卦之序，始乾终坤。盖奇画耦画之上，每加一奇一耦，二而四，四而八，八而十六，十六而三十二，以极于六十四，乃其生卦自然之序，非人所安排也。后之易，各因羲皇之卦，而其序不同。如连山之首艮，归藏之首坤，不复可知其六十四卦之序何如矣。始乾、坤，终既济、未济者，周易六十四卦之序也。盖文王既立卦名之后，而次其先后之序如此，皆以施用于人事者起义，而夫子为之传，以发明其卦序之意。或者乃疑其非夫子之作。张子曰：序卦不可谓非圣人之蕴，其间虽无极至精义，大槩皆有意思。今欲安置一物，犹求审处，况圣人之于易，必须布遍精密如是，大匠岂以一斧可知哉！",-1),a("p",null,"有天地，然后万物生焉。 此言乾坤所以为上经之首也。天地，谓乾、坤二卦。 盈天地之间者唯万物，故受之以屯。屯者，盈也。屯者，物之始生也。 此言屯所以次乾坤也。盈者，窒塞填满之意也。始生艰难，未能畅达，如人欲吐未吐，欲泻未泻，窒塞填满于中。程子曰：天地生万物，万物之始生，郁结未通，盈塞于天地之间，故继乾坤之后。 物生必蒙，故受之以蒙。蒙者，蒙也，物之稚也。 此言「蒙」所以次屯也。程子曰：屯，物之始生，稚小蒙昩。 物稚不可不养也，故受之以需。需者，饮食之道也。 此言「需」所以次「蒙」也。程子曰：物之幼稚，必待养而成。养物之需者，饮食也。饮食所以润益于物。云上于天，有蒸润之象，故需为饮食之道。 饮食必有讼，故受之以讼。 此言「讼」所以次「需」也。程子曰：人之所需者饮食。既有所需，争讼所由起。 讼必有众起，故受之以师。师者，众也。 此言「师」所以次「讼」也。程子曰：师之兴，犹有争也。 众必有所比，故受之以比。比者，比也。 此言「比」所以次「师」也。程子曰：比，亲辅也。既有众，必相亲辅，然后能安。 比必有所畜，故受之以小畜。 此言「小畜」所以次「比」也。程子曰：物相比辅，则为聚畜。 物畜然后有礼，故受之以履。履者，礼也。 此言履所以次「小畜」也。程子曰：物之聚，则有大小之别，高下之等，美恶之分。是物畜然后有礼。礼，人之所履也。 履而泰，然后安，故受之以泰。泰者，通也。 此言「泰」所以次履也。程子曰：履得其所则舒泰，泰则安矣。 物不可以终通，故受之以否。 此言否所以次「泰」也。程子曰：通泰之极则必否。隔绝不相交通，否也。 物不可以终否，故受之以同人。 此言同人所以次否也。程子曰：天地不交则为否，上下相通则为同。人世之否，与人同力乃能济。 与人同者，物必归焉，故受之以大有。 此言大有所以次同人也。程子曰：与人同者，物之所归。物之所归，为「大有」之义。 有大者不可以盈，故受之以谦。 此言谦所以次大有也。程子曰：有既大，不可至于盈满，必在谦损。 有大而能谦，必豫，故受之以豫。 此言豫所以次谦也。程子曰：有既大而能谦，则有豫乐。豫者，安和悦乐之义，承二卦之义而为次也。 豫必有随，故受之以随。 此言随所以次豫也。程子曰：豫，悦之道，物之所随。 以喜随人者必有事，故受之以蛊。蛊者，事也。 此言蛊所以次随也。程子曰：喜悦以随于人者，必有事也。无事则何喜何随？承二卦之义以为次。蛊非训事，蛊乃有事也。 有事而后可大，故受之以临。临者，大也。 此言临所以次蛊也。程子曰：韩康伯云：可大之业，由事而生。二阳方长而盛大为临。澄谓：因蛊之有事，而后有临之盛大也。 物大然后可观，故受之以观。 此言观所以次临也。物之小者在下，视之而不见，必大而后可以观也。以临卦二阳之大，反易其体，则大者在上矣，故为在下四阴之所观。 可观而后有所合，故受之以噬嗑。嗑者，合也。 此言「噬嗑」所以次观也。程子曰：既有所观，然后有来合之者。 物不可以苟合而已，故受之以贲。贲者，饰也。 此言「贲」所以次噬嗑也。不执贽，则不可以成宾主之合；不受币，则不可以成男女之合。程子曰：物之合，必有文饰也。 致饰然后亨则尽矣，故受之以剥；剥者，剥也。 此言剥所以次贲也。致其文饰，而百嘉聚会，则华美之极至矣尽矣。程子曰：极则必反，故贲终则剥也。 物不可以终尽剥，穷上反下，故受之以复。 此言复所以次剥也。程子曰：物无剥尽之理，故剥极则复。阳剥极于上，而复生于下，穷上而反下也。 复则不妄矣，故受之以无妄。 此言「无妄」所以次复也。程子曰：复者，反于道也。既复于道，则合正理而无妄 有。无妄然后可畜，故受之以大畜。 此言大畜所以次无妄也。程子曰：无妄则为有实，故可畜聚。 物畜然后可养，故受之以颐；颐者，养也。 此言「颐」所以次大畜也。程子曰：物既畜聚，则必有以养，无养则不能存息。项氏曰：需当物生之初，如儿之须乳，苖之须溉，故曰饮食之道。颐当畜聚之极，万物交致其养，故曰「养也」。 不养则不可动，故受之以大过。 此言大过所以次颐也。程子曰：凡物养而后能成，成则能动，动则有过。 物不可以终过，故受之以坎；坎者，陷也。 此言坎所以次大过也。程子曰：过极则必陷， 陷必有所丽，故受之以离；离者，丽也。 此言离所以次坎也。程子曰：陷于险难之中，则必有所附丽。传九之一章，凡四百九字。「故受之以履」下，旧本无「履者礼也」四字，韩注有之。今案王弼略例引此四字，盖是后人误以正文书作注字。否，备鄙切。观，平声。注填音田。上于、时掌切。之别，彼列切。豫乐音洛方。长，知两切。坎难乃旦反。 有天地，然后有万物；有万物，然后有男女；有男女，然后有夫妇；有夫妇，然后有父子；有父子，然后有君臣；有君臣，然后有上下；有上下，然后礼义有所错。 此言咸所以为下经之首也。夫妇，谓咸卦。先言天地、万物、男女者，有夫妇之所由也；后言父子、君臣、上下者，有夫妇之所致也。有夫妇，则其所生为父子。由家而国，虽非父子，而君尊臣卑之分，如父子也；由国而天下，虽非君臣，而上贵下贱之分，如君臣也。礼义所以分别尊卑贵贱之等。错，犹置也。乾、坤、咸不出卦名者，以其为上下篇之首卦，特别异之。程子曰：天地，万物之本；夫妇，人伦之始。所以上经首乾、坤，下经首咸、恒也。 夫妇之道，不可以不久也，故受之以恒。恒者，久也。 此言「恒」所以次咸也。程子曰：「咸」，夫妇之道，夫妇终身不变者。 物不可以久居其所，故受之以遁；遁者，退也。 此言遁所以次恒也。程子曰：久则有去。 物不可以终遁，故受之以「大壮」。 此言「大壮」所以次「遁」也。程子曰：「遁」为违去之义，「壮」为进盛之义。遁者，阴长而阳遁。「大壮」，阳之壮盛也。衰则必盛，消息相须，故既遁则必壮。 物不可以终壮，故受之以晋；晋者，进也。 此言「晋」所以次「大壮」也。程子曰：物无壮而止之理，既盛壮则必进。 进必有所伤，故受之以「明夷」；「夷」者，伤也。 此言「明夷」所以次「晋」也。程子曰：进而不己，必有所伤。 伤于外者，必反其家，故受之以家人。 此言「家人」所以次「明夷」也。程子曰：伤困于外，则必反于内。 家道穷必乖，故受之以睽；「睽」者，乖也。 此言「暌」所以次家人也。程子曰：家道穷，则暌乖离散。 乖必有难，故受之以蹇；蹇者，难也。 此言「蹇」所以次「睽」也。程子曰：暌乖之时，必有蹇难。 物不可以终难，故受之以解。解者，缓也。 此言解所以次蹇也。程子曰：难极则必散。解者，散也。 缓必有所失，故受之以损。 此言「损」所以次解也。程子曰：缓纵则必有所失，失则损。 损而不已必益，故受之以益。 此言「益」所以次损也。程子曰：盛衰损益如循环。损极必益。 益而不已必决，故受之以夬；夬者，决也。 此言夬所以次益也。程子曰：理无常益，益之极必溃矣。 决必有遇，故受之以姤；姤者，遇也。 此言姤所以次夬也。程子曰：夬，判也。物之决判，则有遇合，不合则何遇？ 物相遇而后聚，故受之以萃；萃者，聚也。 此言萃所以次姤也。程子曰：物相会遇，必成群聚。 聚而上者谓之升，故受之以升。 此言升所以次萃也。程子曰：物之积聚而益高大，聚而上也，故为升。 升而不己必困，故受之以困。 此言困所以次升也。程子曰：升者，自下而上。自下升上，以力进也，不己必困矣。 困乎上者必反下，故受之以井。 此言井所以次困也。程子曰：上升不己也而困，则必反于下。物之在下者莫如井， 井道不可不革，故受之以革。 此言革所以次井也。程子曰：井之为物，存之则秽败，易之则清洁，不可不革者也。 革物者莫若鼎，故受之以鼎。 此言鼎所以次「革」也。程子曰：鼎之为用，变腥而为熟，易坚而为柔。水火不可同处也，能使相合为用而不相害，是能革物也。 主器者莫若长子，故受之以震。震者，动也。 此言「震」所以次鼎也。程子曰：鼎者，器也。震为长男，传国家、继位号者也。故为主器之主，而继鼎之后。 物不可以终动，止之，故受之以艮。艮者，止也。 此言艮所以次震也。程子曰：动静相理，因静则有动，动则有静。物无常动之 物，不可以终止，故受之以渐。渐者，进也。 此言「渐」所以次「艮」也。程子曰：进以序为渐，今人以缓进为渐。进止必有进，止之所生亦进也；所反亦进也。 进必有所归，故受之以归妹。 此言归妹所以次渐也。程子曰：进必有所至，故渐有归义。项氏曰：晋之义，进而明也。明之极，必至于无进，故有所伤。渐之义，不急于进，其进以渐，故得其所归也。 得其所归者必大，故受之以丰；丰者，大也。 此言「丰」所以次「归妹」也。程子曰：「物所归聚，必成其大。」澄谓：临之大，以其所临之二阳为大；丰之大，以其卦名为盛大之义。 穷大者必失其居，故受之以旅。 此言「旅」所以次「丰」也。程子曰：「丰盛至于穷极，则必失其所安。」 旅而无所容，故受之以巽；巽者，入也。 此言「巽」所以次「旅」也。程子曰：羁旅亲寡，非巽顺何所取容？苟能巽顺，虽旅困之中，何往而不能入？ 入而后说之，故受之以兑；兑者，说也。 此言「兑」所以次「巽」也。程子曰：物相入则相说。 说而后散之，故受之以涣。涣者，离也。 此言「涣」所以次「兑」也。程子曰：人之气忧则结聚，说则舒散。 物不可以终离，故受之以节。 此言「节」所以次「涣」也。程子曰：物既离散，则当节止之。 节而信之，故受之以中孚。 此言「中孚」所以次「节」也。程子曰：节者，为之制节，使不得过越也。信而后能行，上能信守之，下则信从之，节而信之也。 有其信者必行之，故受之以小过。 此言「小过」所以次「中孚」也。项氏曰：有其信，犹书所谓「有其善」，言以此自负而居有之也。自恃其信者，其行必果而过于中。程子曰：「信则必行，行则过也。」澄谓：过者，行动而逾越之也。故大过云「动」，小过云「行」。凡行动未至其所为未及，既至其所为至，既至而又动又行，则为逾越其所至之地而过也。 有过物者必济，故受之以既济。 此言既济所以次小过也。人卑，才智逾越于人为过。程子曰：能过于物，必可以济。项氏曰：大过则逾越常理，故必至于陷。小过则或可济事，故有济而无陷也。 物不可穷也，故受之以未济终焉。 此言未济所以次既济，而为六十四卦之终也。程子曰：既济矣，物之穷也。物穷而不变，则无不己之理。易者变易而不穷也。既济之后，受以未济，则未穷也。",-1),a("p",null,"传九之二章，凡五百二字。错，七路切。难，乃旦切。解音蟹。而上，时掌切。长子，知两切。说音曰。注之分，扶问切。分别、别异，并彼列切。阴长，知两切。吕氏大圭曰：序卦之意，有以相因为序，如屯、蒙、需、讼是也。有以相反为序，如泰、否、同人是也。天地间不出相反相因而已。 易纂言卷十一。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
